/*
 * tests/parity/gemm_vp_modes_emit.c -- C-side emitter of the gemm_vp_modes parity family
 * (the register-staged global prefetch body of the universal GEMM; see
 * _gemm_vp_common.py). Builds the specs of gemm_vp_modes_emit.py (same order, same
 * values) through the C API so run_diff.py can byte-compare the two engines.
 * The case rows are generated: `python gemm_vp_modes_emit.py --c-cases`.
 *
 * vgpr_prefetch modes 1-4 with depth 1-3, vp_unroll, the mode-4 main-loop levers singly and combined, pads (tight resources), the K tail, split-K (atomic, aligned slices, in-launch serial reduction), swizzle / schedule / epilogue variants, gfx950, and the out_f32 prologue.
 */
